/**
 * 负责按遗言政策判定资格，并为已死亡玩家发表遗言授予事实。
 * 输入为死亡阶段、日期、原死因及可选初始波上下文；记录入口另接收 World 与待写事件数组。
 * 输出为资格布尔值和 last_words_granted 事件；实际生命仍在写入前检查，规则未知则拒绝。
 * 此机制不执行玩家发言、更新死亡波或判胜，发言与阶段推进归原调用流程。
 */
/** 文件说明：遗言规则与事件写入机制。 */
import type { LastWordsPolicy } from "../../../core/domain/board";
import { AliveComponent } from "../../../core/domain/components/alive";
import { COMPONENT } from "../../../core/domain/components/names";
import {
  EntityId,
  GameEvent,
  Phase,
  DeathCause,
  type DeathSources,
} from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { FRAGRANT_PAIR_POLICY } from "@ai-werewolf-arena/game-contract/facts/fragrant-pair-seer";
export interface LastWordsGrantContext {
  policy: typeof FRAGRANT_PAIR_POLICY;
  initialWave: boolean;
}

/** 遗言机制：判定是否可遗言并写入遗言授权事件。 */
export class LastWordsMechanism {
  /** 这里只判来源阶段、日期与死因；基础政策是否初始波由调用方筛选，不凭资格布尔值直接开放发言。 */
  shouldGrantLastWords(
    deathPhase: Phase,
    day: number,
    sources: readonly DeathCause[],
    policy: LastWordsPolicy = "awa_initial_wave_v1",
    context?: LastWordsGrantContext,
  ): boolean {
    // 具名政策要求全部原因已知，再允许白天／投票及首夜夜死；不借当前执行阶段猜测死亡来源。
    if (policy === "netease_2017_day_and_first_night_v1") {
      if (!sources.length || sources.some((source) => !Object.values(DeathCause).includes(source)))
        return false;
      return (
        deathPhase === Phase.Day ||
        deathPhase === Phase.Voting ||
        (deathPhase === Phase.Night && day === 1)
      );
    }
    if (policy !== "awa_initial_wave_v1") return false;
    if (
      sources.length === 0 ||
      sources.includes(DeathCause.SelfDestruct) ||
      sources.includes(DeathCause.WhiteWolfBlast)
    )
      return false;
    if (deathPhase === Phase.Day && sources.every((source) => source === DeathCause.DuelFailure))
      return true;
    return (
      (deathPhase === Phase.Night &&
        day === 1 &&
        sources.some(
          (source) =>
            source === DeathCause.WolfKill ||
            (source === DeathCause.FragrantLink &&
              context?.policy === FRAGRANT_PAIR_POLICY &&
              context.initialWave) ||
            source === DeathCause.AwakenedHiddenKnife ||
            source === DeathCause.Poison ||
            source === DeathCause.Dream ||
            source === DeathCause.FoxInspection ||
            source === DeathCause.MerchantBacklash ||
            source === DeathCause.BlackMarketBacklash,
        )) ||
      (deathPhase === Phase.Voting && sources.includes(DeathCause.Exile))
    );
  }

  /** 逐人再次核死因政策与实际死亡，只写授予事实；等待玩家、打开生命许可和记录发言归结算器。 */
  recordLastWordsGranted(
    world: World,
    deadIds: EntityId[],
    deathPhase: Phase,
    lastWordsPhase: Phase,
    day: number,
    events: GameEvent[],
    sources: DeathSources,
    deathPhases: Readonly<Record<EntityId, Phase>> = {},
    policy: LastWordsPolicy = "awa_initial_wave_v1",
    context?: LastWordsGrantContext,
  ): void {
    for (const deadId of deadIds) {
      if (
        !this.shouldGrantLastWords(
          deathPhases[deadId] ?? deathPhase,
          day,
          sources[deadId] ?? [],
          policy,
          context,
        )
      ) {
        continue;
      }
      const alive = world.getComponent(deadId, COMPONENT.Alive);
      if (!alive || alive.alive) {
        continue;
      }
      events.push({
        timestamp: Date.now(),
        type: "last_words_granted",
        payload: {
          playerId: deadId,
          phase: lastWordsPhase,
          day,
        },
      });
    }
  }
}

let defaultMechanism: LastWordsMechanism | null = null;

/** 获取默认遗言机制实例。 */
export function getDefaultLastWordsMechanism(): LastWordsMechanism {
  if (!defaultMechanism) {
    defaultMechanism = new LastWordsMechanism();
  }
  return defaultMechanism;
}

/**
 * 负责实体 ID、组件 Map 与原生命绑定的临时死亡行动许可。输入为既有实体／槽操作及
 * 生命周期回调，输出保持原可写组件引用、筛选结果和许可 ID。World 唯一写入自己的存储，
 * 工厂与角色所有者仍负责值和资源校验；槽推断不增加运行守卫、复制或冻结。
 * 旧任意组件类型 T 重载已退出，读写关系由具名槽约束；死亡许可仍按原生命版本与当前性撤销，ID 本身不授权。
 */
import { EntityId, Phase, Role } from "./model";
import { COMPONENT, ComponentName } from "./components/names";
import type { ComponentMap, ComponentWrite } from "./component-map";
import { AliveComponent, aliveLifeVersion } from "./components/alive";
import { RoleComponent } from "./components/role";
import { isLocale, type Locale } from "@ai-werewolf-arena/game-contract";

/**
 * World 是 ECS 内存状态容器。
 * 设计目标：保持结构简单、读写明确，所有系统都基于该容器进行组件查询与变更。
 */
export class World {
  constructor(readonly locale: Locale = "zh-CN") {
    if (!isLocale(locale)) throw new Error("game_locale_invalid");
  }
  private nextId: EntityId = 1;
  private entities: Set<EntityId> = new Set();
  private stores: Map<ComponentName, Map<EntityId, unknown>> = new Map();
  private nextDeathActionId = 1;
  // 许可绑定原 Alive 对象和该对象的生命版本；复活、替换组件或失去当前性均撤销旧许可。
  private deathActions = new Map<
    EntityId,
    {
      id: number;
      tool: "shoot" | "speak" | "choose_badge_successor";
      phase: Phase;
      day: number;
      abilityId?: string;
      alive: AliveComponent;
      lifeVersion: number;
      isCurrent: () => boolean;
    }
  >();

  /** 引擎拥有的临时行动许可；ID 不授予行动。World 复核原生命与传入的当前性回调，带阶段的查询另核许可记录的 phase／day。 */
  openDeathAction(
    actorId: EntityId,
    tool: "shoot" | "speak" | "choose_badge_successor",
    phase: Phase,
    day: number,
    isCurrent: () => boolean = () => true,
    abilityId?: string,
  ): { readonly id: number; close(): void } {
    if (this.currentDeathAction(actorId)) throw new Error("death_action_already_open");
    const alive = this.getComponent(actorId, COMPONENT.Alive);
    const lifeVersion = alive && aliveLifeVersion(alive);
    if (
      !alive ||
      alive.alive !== false ||
      lifeVersion === undefined ||
      !this.getComponent(actorId, COMPONENT.Role) ||
      !Number.isSafeInteger(day) ||
      day < 1 ||
      !["shoot", "speak", "choose_badge_successor"].includes(tool) ||
      !Object.values(Phase).includes(phase) ||
      phase === Phase.GameOver ||
      (abilityId !== undefined &&
        (tool !== "shoot" ||
          typeof abilityId !== "string" ||
          !/^[a-z][a-z0-9:_-]{0,127}$/.test(abilityId) ||
          abilityId.startsWith("native:")))
    ) {
      throw new Error("death_action_invalid_actor_or_stage");
    }
    const id = this.nextDeathActionId++;
    this.deathActions.set(actorId, {
      id,
      tool,
      phase,
      day,
      abilityId,
      alive,
      lifeVersion,
      isCurrent,
    });
    return Object.freeze({
      id,
      close: () => {
        if (this.deathActions.get(actorId)?.id === id) this.deathActions.delete(actorId);
      },
    });
  }

  hasDeathAction(
    actorId: EntityId,
    tool: string,
    phase: Phase,
    day: number | undefined,
    id: number | undefined,
    abilityId?: string,
  ): boolean {
    const permit = this.currentDeathAction(actorId);
    return (
      permit !== undefined &&
      permit.id === id &&
      permit.tool === tool &&
      permit.phase === phase &&
      permit.day === day &&
      permit.abilityId === abilityId
    );
  }

  isDeathActionOpen(actorId: EntityId, tool: string, id: number, abilityId?: string): boolean {
    const permit = this.currentDeathAction(actorId);
    return (
      permit !== undefined &&
      permit.id === id &&
      permit.tool === tool &&
      permit.abilityId === abilityId
    );
  }

  private currentDeathAction(actorId: EntityId) {
    const permit = this.deathActions.get(actorId);
    if (!permit) return undefined;
    if (
      this.getComponent(actorId, COMPONENT.Alive) !== permit.alive ||
      permit.alive.alive !== false ||
      aliveLifeVersion(permit.alive) !== permit.lifeVersion ||
      !permit.isCurrent()
    ) {
      this.deathActions.delete(actorId);
      return undefined;
    }
    return permit;
  }

  get activeDeathActionCount(): number {
    for (const actorId of this.deathActions.keys()) this.currentDeathAction(actorId);
    return this.deathActions.size;
  }

  closeDeathActions(): void {
    this.deathActions.clear();
  }

  /**
   * 创建新实体并返回实体 ID。
   */
  createEntity(): EntityId {
    const id = this.nextId++;
    this.entities.add(id);
    return id;
  }

  /**
   * 判断实体是否存在。
   */
  hasEntity(entityId: EntityId): boolean {
    return this.entities.has(entityId);
  }

  /**
   * 返回当前所有实体 ID（升序）。
   */
  entityIds(): EntityId[] {
    return [...this.entities].sort((a, b) => a - b);
  }

  addComponent<K extends ComponentName, C extends ComponentWrite<NoInfer<K>>>(
    entityId: EntityId,
    name: K,
    component: C,
  ): void {
    if (!this.hasEntity(entityId)) {
      throw new Error(`Entity ${entityId} does not exist`);
    }

    // 每类组件一张表，按 entityId 索引。
    const store = this.ensureStore(name);
    store.set(entityId, component);
  }

  getComponent<K extends ComponentName>(entityId: EntityId, name: K): ComponentMap[K] | undefined {
    const store = this.stores.get(name);
    return store?.get(entityId) as ComponentMap[K] | undefined;
  }

  /**
   * 从实体上移除指定组件。
   */
  removeComponent(entityId: EntityId, name: ComponentName): void {
    const store = this.stores.get(name);
    store?.delete(entityId);
  }

  /**
   * 返回同时拥有给定组件集合的实体列表。
   */
  entitiesWith(...names: ComponentName[]): EntityId[] {
    // 只有同时拥有所有组件的实体才会被返回，用于系统筛选。
    return this.entityIds().filter((entityId) => {
      return names.every((name) => {
        const store = this.stores.get(name);
        return store?.has(entityId) ?? false;
      });
    });
  }

  /**
   * 返回当前存活实体 ID 列表。
   */
  getAliveEntityIds(): EntityId[] {
    return this.entitiesWith(COMPONENT.Alive).filter((id) => {
      const alive = this.getComponent(id, COMPONENT.Alive);
      return alive?.alive === true;
    });
  }

  /**
   * 按角色筛选实体 ID。
   */
  getEntityIdsByRole(role: Role): EntityId[] {
    return this.entitiesWith(COMPONENT.Role).filter((id) => {
      const roleComp = this.getComponent(id, COMPONENT.Role);
      return roleComp?.role === role;
    });
  }

  /**
   * 确保组件存储存在，不存在则懒加载创建。
   */
  private ensureStore(name: ComponentName): Map<EntityId, unknown> {
    let store = this.stores.get(name);
    if (!store) {
      // 延迟初始化组件存储，避免为未使用组件提前分配空间。
      store = new Map<EntityId, unknown>();
      this.stores.set(name, store);
    }
    return store;
  }
}

/**
 * 负责从原 World 与明确阶段构造引擎行动请求。输入为演员、窗口、允许工具和中立摘要；
 * 输出固定日次、阶段、约束及玩家可见事实，完整构造之后交规则集按原顺序接线机制绑定。
 * 具体机制仍唯一持有权限、期限别名与资源提交；本工厂不计算或写 deadlineAtMs，请求数据副本不是行动许可。
 * 本工厂不渲染本地化文案、不序列化运行范围，也不据阶段字符串新增角色权限。
 */
import { bindRulesetActionRequest } from "../../rulesets/action-request-bindings";
import type { ActionRequestConstructionInput, ActionRequestConstructionPort } from "../../core/domain/actions";
import type { ActionRequest } from "@ai-werewolf-arena/game-contract/requests";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import { World } from "../../core/domain/world";
import { buildAgentVisibleEventFeed } from "./agent_visible_event_feed";
import { buildTurnConstraintContext } from "./turn_constraints_context";

/**
 * 统一创建游戏对 Agent 的行动请求。
 *
 * 该工厂统一填入原生请求的日次、细粒度 stage、玩家可见事件与结构化行动约束；
 * 调用方提供机制附加数据，运行时权限仍由具体机制保存，不混入这些公共字段。
 * 事件输出按 actorId 投影；日次取构造输入，不从 World 当前时钟重新推断。
 * 完整数据先构造再绑定原请求对象，clone／约束／投影失败时不进入规则集绑定。
 */
export class GameActionRequestFactory implements ActionRequestConstructionPort {
  constructor(
    // 保留原 World／事件数组引用；readonly 仅限制这里的类型写法，不拍摄快照或冻结输入。
    private readonly world: World,
    private readonly events: readonly GameEvent[],
    private readonly day: number,
  ) {}

  create(input: ActionRequestConstructionInput): ActionRequest {
    // 先按原顺序复制 allowedTools，再克隆机制附加 context；运行句柄不可借公共数据副本成为凭据。
    // 后面的公共字段覆盖附加数据中同名字段；不提前缓存 input getter 或吞掉 clone 的原错误。
    const request: ActionRequest = {
      phase: input.phase,
      actorId: input.actorId,
      allowedTools: [...input.allowedTools],
      ...(input.actionWindow ? { actionWindow: input.actionWindow } : {}),
      context: {
        ...structuredClone(input.context ?? {}),
        day: this.day,
        stage: input.stage,
        turn_constraints: buildTurnConstraintContext({
          requiresAction: input.requiresAction,
          allowedTools: input.allowedTools,
          summary: input.summary,
        }),
        // 等约束构造完成才复制当前事件数组并生成该演员视图，不将整份内部事件数组直接当成玩家事实。
        visible_events: buildAgentVisibleEventFeed(this.world, [...this.events], input.actorId),
      },
    };
    // 完整请求原对象交给各机制建立运行关联；ID／context／期限字段本身不能替代原对象绑定。
    // 原输入的阶段仍逐分支读取，不用已构造的 context.stage 替代后续 getter；World 也只在命中时读。
    // 绑定中抛错仍原样传播，已经建立的前面关联不由本工厂回滚。
    bindRulesetActionRequest(request, {
      stage: () => input.stage,
      world: () => this.world,
    });
    return request;
  }
}

/**
 * 负责行动提交前的发言文字清洗与领域预检；输入原 World、行动者、调用和上下文，输出原校验结果。
 * JSON Schema 由 ActionReception 持有；本入口按原清洗 → validator 顺序，不消费库存或提交动作。
 * 实例保存原校验器引用，两种发言分支产生浅副本，其它调用保原引用；不是快照、冻结或新许可。
 * getter、清洗与校验异常原样传播，不统一吞错、补偿或保证任意输入都能得到结构化拒绝。
 */
import { sanitizeSpeechText } from "../../utils/speech_text";
import { EntityId, ToolCall, ToolValidationResult } from "../../core/domain/model";
import { World } from "../../core/domain/world";
import { ActionValidator, type ValidationContext } from "./action_validator";

/**
 * 网关只形成清洗后的领域校验候选；预检通过不代表付款、请求完成或实际效果已发生。
 */
export class ToolGateway {
  private readonly validator: ActionValidator;

  constructor(validator: ActionValidator = new ActionValidator()) {
    this.validator = validator;
  }

  /** 先完成清洗再读取并调用原 validator；清洗抛错时不进入校验器，不提前读取 World 或上下文字段。 */
  validateAndSanitize<T extends ToolCall>(
    world: World,
    actorId: EntityId,
    toolCall: T,
    context: ValidationContext,
  ): ToolValidationResult<T> {
    const sanitizedCall = this.sanitize(toolCall);
    return this.validator.validate(world, actorId, sanitizedCall, context);
  }

  /** 按原 name 分支读取；仅两种发言造新外层／args 对象，不做其它工具的 schema 或权限校验。 */
  private sanitize<T extends ToolCall>(call: T): T {
    if (call.name === "speak") {
      const raw = call.args.text;
      // 仅清除开头的既有保留前缀并 trim；不删内嵌文字，也不把清洗当作身份认证。
      const text = sanitizeSpeechText(raw);
      // 清洗成功后再按原 spread 次序读取调用和 args；仅浅复制，原嵌套引用与 getter 轨迹保持。
      return {
        ...call,
        args: {
          ...call.args,
          text,
        },
      } as T;
    }
    if (call.name === "speak_to_wolves") {
      const raw = call.args.text;
      const text = sanitizeSpeechText(raw);
      return {
        ...call,
        args: {
          ...call.args,
          text,
          // end_chat 在原两个 spread 与 text 之后才读取，保 Boolean truthiness，不做严格布尔校验。
          end_chat: Boolean(call.args.end_chat),
        },
      } as T;
    }
    // 非发言工具不复制、不归一化参数；领域校验仍在上层的原 validator 调用点执行。
    return call;
  }
}

/**
 * 负责请求对象上的交付检查、完成回调和期限别名传播。输入为机制已经绑定的原请求、
 * 当前性查询及不透明完成身份；输出为同步交付检查、一次性结算通知和有序别名绑定。
 * 元数据仅存运行时弱表，不进入模型上下文或归档。机制仍拥有权限、最早期限及单调撤权；
 * 本模块只调用已注册的规则，不以缺少交付检查或相同 JSON 字段判定请求已获授权。
 * 本模块仅写入交付弱表，不修改生命、库存或阶段；结算先删除待通知项再调用回调，异常不恢复。
 * 别名传播遇异常即停止，已完成的绑定不回滚。
 */
import type { ActionRequest } from "./actions";

type AliasPropagation = (original: ActionRequest, alias: ActionRequest) => void;
/** 原请求与别名各自登记元数据；completion 可指向同一机制窗口，不是可序列化许可。 */
interface DeliveryMetadata {
  /** 查询是否可交付；具体原体、生命版本与永久撤权由机制的查询实现负责。 */
  current?: () => boolean;
  /** 将一次 Provider 返回关联到后续领域提交或关闭，不把返回动作当成提交成功。 */
  completion?: object;
  /** 回调身份是键；同一回调重登记只更新顺序，具体别名绑定仍由该机制执行。 */
  aliases?: Map<AliasPropagation, number>;
}

/** 弱表按对象身份关联：复制请求字段不会复制当前性检查或完成身份。 */
const guards = new WeakMap<object, DeliveryMetadata>();
/** 同一完成身份同时最多保留一个待结算回调；原请求和合法别名可共享该身份。 */
const settlements = new WeakMap<object, (accepted: boolean) => void>();
/** 机制成功绑定后登记一次交付检查；保留此前已登记的别名路由。 */
export function bindRequestDeliveryGuard(
  request: object,
  isCurrent: () => boolean,
  completion?: object,
): void {
  const existing = guards.get(request);
  if (existing && "current" in existing)
    throw new Error("action_request_delivery_guard_already_bound");
  guards.set(request, { ...existing, current: isCurrent, completion });
}
/** 无登记时不额外拒绝；有检查时必须严格返回 true，不能用真值替代机制确认。 */
export function assertRequestDelivery(request: ActionRequest): void {
  const guard = guards.get(request);
  if (guard && "current" in guard && guard.current!() !== true)
    throw new Error("action_request_delivery_authority_revoked");
}
/** 登记事务请求的延后通知；无完成身份则返回 false，由调用方执行原有即时通知政策。 */
export function deferRequestDelivery(
  request: ActionRequest,
  settle: (accepted: boolean) => void,
): boolean {
  const completion = guards.get(request)?.completion;
  if (!completion) return false;
  if (settlements.has(completion)) throw new Error("action_request_delivery_already_pending");
  settlements.set(completion, settle);
  return true;
}
export function settleRequestDelivery(completion: object, accepted: boolean): void {
  const settle = settlements.get(completion);
  if (!settle) return;
  // 先消费再通知：重入或回调抛错都不会再次发送同一成功／拒绝通知，也不回滚领域前缀。
  settlements.delete(completion);
  settle(accepted);
}

/** 仅登记已成功绑定的路由；登记自身不会执行回调、校验权限或设置期限。 */
export function registerRequestAliasPropagation(
  request: object,
  order: number,
  inherit: AliasPropagation,
): void {
  let metadata = guards.get(request);
  if (!metadata) {
    metadata = {};
    guards.set(request, metadata);
  }
  (metadata.aliases ??= new Map()).set(inherit, order);
}

/** 机制自行接纳并绑定别名；按顺序调用不等于授予新行动权限。 */
export function inheritRequestAlias(original: ActionRequest, alias: ActionRequest): void {
  const routes = guards.get(original)?.aliases;
  if (!routes) return;
  // 先取路由快照再稳定排序；回调期间增删路由不改变本次名单，抛错时后续路由不执行。
  for (const [inherit] of [...routes].sort((left, right) => left[1] - right[1]))
    inherit(original, alias);
}

/** 调用方先计算最早期限；这里保留原字段展开顺序，再由已登记机制绑定新对象。 */
export function deriveBoundedRequest(original: ActionRequest, deadlineAtMs: number): ActionRequest {
  const alias = { ...original, deadlineAtMs };
  inheritRequestAlias(original, alias);
  return alias;
}

/**
 * 负责有序死亡波、角色死亡钩子、枪击选择、遗言与警徽交接。输入是待处理的死亡名单、
 * 原死因与原生命行动权限；输出是按原顺序提交的死亡、事件和内部关联凭证。实际生命修改和唯一已结算
 * 账本委托 DeathCommitter，双生、动物、婚约及狼美人关系事实归具体贡献；已提交整波在梦／遗言前交角色扩展，
 * 野孩子贡献自行核对榜样原生命。参数仍使用同一深只读规则视图，不建立第二份角色状态。
 * 初始和枪后追加关系准备归各自具名规则组合；本结算器仍在原逐目标时点登记来源阶段、标死并提交／发布双生回执。
 * 未提交预约只在已进入的原 finally 处取消，已提交回执不因后续发布失败而回滚。
 * 枪的资格归共同所有者，请求、等待与目标复验归规则组合；本结算器持同一许可数组并在原时点关闭。
 * 本模块不切换阶段或确定最终胜负；关系扩展、遗言、警徽和枪的最终过期保留原执行顺序。
 */
